fn finish(){assert_eq!(load(r("runs/result.json"))["status"],"complete");let pins=load(r("pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}for(dir,plan)in[("native","native-plan.json"),("runs","run-plan.json")]{for s in load(r(plan))["steps"].as_array().unwrap(){let n=s["name"].as_str().unwrap();let e=load(r(format!("{dir}/{n}/exit.json")));assert_eq!(e["success"],true);assert_eq!(e["returncode"],0);for stream in["stdout","stderr"]{assert_eq!(hash(r(format!("{dir}/{n}/{stream}.log"))),e[format!("{stream}_sha256")]);}}}
 let jobs=load(r("jobs.json"));let mut rows=BTreeMap::<String,Vec<Value>>::new();let mut profiles=BTreeMap::new();let mut signatures=BTreeMap::<String,Value>::new();let mut calls=0u64;let mut primes=0u64;let mut point_calls=0u64;
 for j in jobs.as_array().unwrap(){let parsed=parse(j);let v=&parsed["raw"];let c=&j["context"];let ctx=c["name"].as_str().unwrap();let n=j["name"].as_str().unwrap();calls+=v["total_kernel_calls"].as_u64().unwrap();primes+=3*v["prime_iterations_per_worker"].as_u64().unwrap()*v["worker_count"].as_u64().unwrap();point_calls+=v["total_kernel_calls"].as_u64().unwrap()*c["size"].as_u64().unwrap();let signature=json!({"output":v["output_sha256"],"capacity":v["capacity_bytes_per_worker"],"references":v["fixture_reference_bytes_per_worker"]});let key=format!("{ctx}/{}",j["rounds"]);if let Some(old)=signatures.insert(key,signature.clone()){assert_eq!(old,signature);}if j["phase"]=="latency"{rows.entry(ctx.into()).or_default().push(json!({"block":j["block"],"name":n,"ns_per_point":parsed["ns_per_point"],"raw":v}));}
 if j["phase"]=="profile"{let text=fs::read_to_string(r(format!("runs/decode-{n}/stdout.log"))).unwrap();assert!(!text.contains("PERF_RECORD_LOST"));let mut pid=BTreeSet::new();let tids=v["workers"].as_array().unwrap().iter().map(|w|w["tid"].as_i64().unwrap()).collect::<BTreeSet<_>>();let allowed=v["cpus"].as_array().unwrap().iter().map(|c|c.as_u64().unwrap()).collect::<BTreeSet<_>>();let mut symbols=BTreeMap::<String,u64>::new();let mut samples=0;let mut cpus=BTreeSet::new();for line in text.lines().filter(|l|!l.trim().is_empty()&&!l.trim().starts_with('#')){let fields=line.split_whitespace().collect::<Vec<_>>();assert!(fields.len()>=5,"{line}");let(pp,tt)=fields[0].split_once('/').unwrap();let pp=pp.parse::<i64>().unwrap();let tt=tt.parse::<i64>().unwrap();pid.insert(pp);assert!(tids.contains(&tt)||pp==tt);let cpu=fields[1].trim_matches(['[',']']).parse::<u64>().unwrap();assert!(allowed.contains(&cpu));cpus.insert(cpu);let period=fields[2].parse::<u64>().unwrap();assert_eq!(period,16000000);*symbols.entry(fields[4..].join(" ")).or_default()+=period;samples+=1;}assert_eq!(pid.len(),1);let total=symbols.values().sum::<u64>();let unknown=symbols.iter().filter(|(s,_)|s.contains("unknown")).map(|(_,n)|*n).sum::<u64>();let share=if total==0{1.}else{unknown as f64/total as f64};assert!(fs::read_to_string(r(format!("runs/loss-{n}/stdout.log"))).unwrap().starts_with("ZERO_LOST"));profiles.insert(n.to_owned(),json!({"samples":samples,"PIDs":pid,"CPUs":cpus,"zero_lost":true,"unknown_period_share":share,"qualified":samples>=1000&&share<=0.05,"low_sample_count_retained_without_rerun":samples<1000,"symbol_periods":symbols,"raw_sha256":hash(r(format!("perf/{n}.data"))),"period":16000000,"absolute_period_coverage_not_validated":true}));}}
 assert_eq!(jobs.as_array().unwrap().len(),292);let mut cells=BTreeMap::new();for(k,rs)in&rows{assert_eq!(rs.len(),15);for(i,r)in rs.iter().enumerate(){assert_eq!(r["block"],i);}cells.insert(k.clone(),json!({"median_ns_per_point":median(rs.iter().map(|r|r["ns_per_point"].as_f64().unwrap()).collect()),"blocks":rs}));}assert_eq!(cells.len(),18);let mut pairs=BTreeMap::new();let mut checks=BTreeMap::new();for curve in["g1","g2"]{let budget=if curve=="g1"{24997f64/18626.}else{50652f64/27919.};for topo in["solo","physical16","logical32"]{for reference in[200,352]{let ratios=(0..15).map(|b|rows[&format!("{curve}-1024-{topo}")][b]["ns_per_point"].as_f64().unwrap()/rows[&format!("{curve}-{reference}-{topo}")][b]["ns_per_point"].as_f64().unwrap()).collect::<Vec<_>>();let mut sorted=ratios.clone();sorted.sort_by(f64::total_cmp);let key=format!("{curve}/{topo}/triple1024/add{reference}");let pass=sorted[11]<budget;if topo!="solo"{checks.insert(key.clone(),pass);}pairs.insert(key,json!({"median":sorted[7],"low":sorted[3],"high":sorted[11],"budget":budget,"ratios":ratios,"wins_against_budget":ratios.iter().filter(|&&r|r<budget).count(),"budget_upper_passed":pass,"solo_diagnostic_only":topo=="solo"}));}}}let failed=checks.iter().filter(|(_,v)|!**v).map(|(k,_)|k.clone()).collect::<Vec<_>>();let a=json!({"complete":true,"formation_budget_screen_passed":failed.is_empty(),"failed_checks":failed,"checks":checks,"pairs":pairs,"cells":cells,"profiles":profiles,"processes_checked":292,"workflow_steps":309,"native_core_unfiltered_tests":128,"Ark_oracle_G1":3712,"Ark_oracle_G2":3712,"timed_allocations_all_zero":true,"measured_kernel_calls":calls,"prime_kernel_calls":primes,"total_kernel_calls":calls+primes,"measured_point_calls":point_calls,"production_changed":false,"adopted":false,"new_SDK_requests":0,"new_Gnark_exports":0,"proof_ledger":29461,"goal_achieved":false,"scope":"syntheticcompleteformationcaller versusactualborrowedaddkernel; no SDK/criticalpath/speedupclaim"});save(r("analysis.json"),&a);save(r("rows.json"),&json!(rows));println!("Formationbudgetscreen{} failed{};{}measuredkernels+{}primes;4profiles;0SDK/ledger29461unchanged",a["formation_budget_screen_passed"],a["failed_checks"],calls,primes);for(k,v)in pairs{println!("{k} ratio{:.6}[{:.6},{:.6}]budget{:.6}",v["median"].as_f64().unwrap(),v["low"].as_f64().unwrap(),v["high"].as_f64().unwrap(),v["budget"].as_f64().unwrap());}}
